function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function parseKV(t){
  return splitLines(t).map(function(l){
    var i=l.indexOf(':'), j=l.indexOf('：');
    var pos=-1; if(i>=0&&(j<0||i<j)) pos=i; else if(j>=0) pos=j;
    if(pos<=0) return {k:l.trim(), v:''};
    return {k:l.slice(0,pos).trim(), v:l.slice(pos+1).trim()};
  }).filter(function(x){return x.k;});
}
function buildDatasetCard(o){
  o=o||{};
  var name=String(o.name||'').trim()||'UnnamedDataset';
  var type=String(o.type||'文本').trim()||'文本';
  var domain=String(o.domain||'').trim()||'（待补充领域）';
  var source=String(o.source||'').trim()||'（待补充来源）';
  var size=String(o.size||'').trim()||'（待补充规模）';
  var fmt=String(o.format||'').trim()||'（待补充格式）';
  var license=String(o.license||'').trim()||'（待补充许可证）';
  var desc=String(o.summary||'').trim()||'（待补充描述）';
  var uses=splitLines(o.uses); if(!uses.length) uses=['（待补充预期用途）'];
  var limits=splitLines(o.limits); if(!limits.length) limits=['（待补充已知局限与偏差）'];
  var bias=splitLines(o.bias); if(!bias.length) bias=['建议在发布前做代表性与偏见审计'];
  var splits=parseKV(o.splits);
  var lines=[];
  lines.push('# 数据集卡片：'+name);
  lines.push('');
  lines.push('## 一、概述');
  lines.push('- 类型：'+type);
  lines.push('- 领域：'+domain);
  lines.push('- 描述：'+desc);
  lines.push('');
  lines.push('## 二、预期用途');
  uses.forEach(function(u){ lines.push('- '+u); });
  lines.push('');
  lines.push('## 三、数据构成');
  lines.push('- 来源：'+source);
  lines.push('- 规模：'+size);
  lines.push('- 格式：'+fmt);
  if(splits.length){ lines.push('- 划分：'); splits.forEach(function(s){ lines.push('  - '+s.k+'：'+s.v); }); }
  lines.push('');
  lines.push('## 四、许可与合规');
  lines.push('- 许可证：'+license);
  lines.push('- 个人信息：需确认是否含 PII，是否完成脱敏与授权');
  lines.push('');
  lines.push('## 五、已知局限与偏差');
  limits.forEach(function(l){ lines.push('- '+l); });
  lines.push('');
  lines.push('## 六、质量与偏见审计');
  bias.forEach(function(b){ lines.push('- '+b); });
  return {title:name+' 数据集卡片', useCount:uses.length, limitCount:limits.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, parseKV:parseKV, buildDatasetCard:buildDatasetCard};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DatasetCardForgePure = EXPORTS; }
